import { db } from './client'
import type { Post } from './types'

export type UserId = string
export type PostId = string

export async function findPost(userId: UserId, postId: PostId): Promise<Post | null> {
  return db.post.find({ where: { id: postId, authorId: userId } })
}

export async function loadFeed(userId: UserId, postIds: PostId[]): Promise<(Post | null)[]> {
  return Promise.all(postIds.map((postId) => findPost(postId, userId)))
}

