const USER_ID = /^u_[0-9a-f]{8}$/

export function isUserId(value: string): value is UserId {
  return USER_ID.test(value)
}

export function asUserId(value: string): UserId {
  if (!isUserId(value)) throw new TypeError(`not a UserId: ${value}`)
  return value
}

export const PREFIX: Record<string, string> = {
  user: 'u_',
  post: 'p_',
}

export type IdKind = keyof typeof PREFIX

